CREATE TABLE workforce_seller (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenancy_company(id), user_id UUID NOT NULL REFERENCES identity_access_account(id), display_name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(30), employee_code VARCHAR(50), supervisor_id UUID REFERENCES identity_access_account(id), status VARCHAR(16) NOT NULL CHECK (status IN ('ACTIVE','INACTIVE')), created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version BIGINT NOT NULL, UNIQUE (tenant_id, user_id));
CREATE TABLE workforce_seller_territory (seller_id UUID NOT NULL REFERENCES workforce_seller(id) ON DELETE CASCADE, territory_id UUID NOT NULL REFERENCES workforce_territory(id), PRIMARY KEY (seller_id, territory_id));
CREATE INDEX ix_workforce_seller_tenant ON workforce_seller(tenant_id,id);
